import openpyxl
from openpyxl.utils import get_column_letter

path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path,data_only=False)
ws=wb['Data']

print('Data max_row/max_col', ws.max_row, ws.max_column)

# Show rows 18-24 columns A-L
for r in range(18,25):
    parts=[]
    for c in range(1,13):
        v=ws.cell(r,c).value
        parts.append(f"{get_column_letter(c)}{r}={v!r}")
    print('ROW', r, ' | '.join(parts))

# Find year headers 2020-2024 in sheet
years=[2020,2021,2022,2023,2024]
found=[]
for row in ws.iter_rows():
    for cell in row:
        if cell.value in years:
            found.append((cell.coordinate, cell.value))
print('\nFound year cells:', found[:50])

# Find series codes from Task in Data
series=[
 'AUT_BGT_PRES','CHK_BGT_PRES','SRC_BGT_PRES','PRF_BGT_PRES','CAT_BGT_PRES','NTF_BGT_PRES',
 'AUT_BGT_USE','CHK_BGT_USE','SRC_BGT_USE','PRF_BGT_USE','CAT_BGT_USE','NTF_BGT_USE',
 'AUT_REQ_CAP','CHK_REQ_CAP','SRC_REQ_CAP','PRF_REQ_CAP','CAT_REQ_CAP','NTF_REQ_CAP'
]
coords={}
for s in series:
    coords[s]=[]
for row in ws.iter_rows():
    for cell in row:
        if cell.value in coords:
            coords[cell.value].append(cell.coordinate)

print('\nSeries code locations (non-empty):')
for s in series:
    if coords[s]:
        print(' ',s, coords[s])

# Determine bounding box of non-empty cells in Data
min_r=10**9; max_r=0; min_c=10**9; max_c=0; count=0
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        if ws.cell(r,c).value not in (None,''):
            count += 1
            if r<min_r: min_r=r
            if r>max_r: max_r=r
            if c<min_c: min_c=c
            if c>max_c: max_c=c
print(f"\nNon-empty bounding box: rows {min_r}-{max_r}, cols {min_c}-{max_c} ({get_column_letter(min_c)}-{get_column_letter(max_c)}), non-empty cells {count}")

wb.close()
